/* @autogenerated */
import { AbstractControl, FormGroup, ValidatorFn } from '@angular/forms';

/**
 * Precondición de la entidad sobre un formulario: `check` recibe el valor completo del formulario y,
 * si no se cumple, marca con el error `precondition-<name>` cada control de `fields` (los campos que
 * lee la condición), para que lo muestre su editable.
 *
 * Mensaje: `<label>.error.precondition-<name>` del campo o el común `validation.precondition-<name>`.
 * Al cambiar cualquier campo se revalidan los implicados, porque dependen unos de otros.
 */
export function bindFormPrecondition<T>(
  form: FormGroup,
  name: string,
  fields: string[],
  check: (value: T) => boolean,
): void {
  const key = `precondition-${name}`;
  const controls = fields.map((field) => form.get(field)).filter((control): control is AbstractControl => !!control);
  if (controls.length === 0) {
    return;
  }
  const validator: ValidatorFn = () => (check(form.getRawValue() as T) ? null : { [key]: true });
  controls.forEach((control) => control.addValidators(validator));
  let revalidating = false;
  form.valueChanges.subscribe(() => {
    if (revalidating) {
      return;
    }
    revalidating = true;
    try {
      controls.forEach((control) => control.updateValueAndValidity({ onlySelf: true }));
      form.updateValueAndValidity();
    } finally {
      revalidating = false;
    }
  });
  controls.forEach((control) => control.updateValueAndValidity({ onlySelf: true }));
  form.updateValueAndValidity({ emitEvent: false });
}
